<template>
 <section class="qph-access" :class="{'is-password-login':mode==='login'}" :aria-label="ct('手机账户入口')">
  <div class="qph-story"><span class="qph-eyebrow">A SMALL SIGNAL. A FAMILIAR SPACE.</span><h3>{{ct(mode==='login'?'一个熟悉的号码。':mode==='register'?'让新灵感，有个归处。':'号码记得，回来的路。')}}</h3><p>{{ct(mode==='login'?'用手机号与密码，继续你的 QGauss 创作。':mode==='register'?'确认号码、取个名字，再给空间设置一把钥匙。':'用短信确认这个号码，再设置新的登录密码。')}}</p><span aria-hidden="true" class="qph-story-orbit">✦</span></div>
  <div v-if="!policy" class="qph-policy" role="status"><BrandLoader v-if="policyLoading" :size="18"/>{{ct(policyLoading?'正在确认手机服务…':'暂时无法确认手机服务，请重新读取。')}}<button v-if="!policyLoading" type="button" @click="loadPolicy">{{ct('重新读取')}}</button></div>
  <form class="qph-form" novalidate @submit.prevent="submit">
   <label :for="phoneId">{{ct('手机号码')}}</label><div class="qph-number"><span>{{ct('中国大陆')}} <b>+86</b></span><input :id="phoneId" v-model="form.phone" type="tel" inputmode="tel" autocomplete="tel-national" maxlength="28" :disabled="locked||codeBusy" :placeholder="ct('填写十一位手机号码')" :aria-invalid="!!fieldError.phone" @focus="focus('phone')" @blur="focus('none')" @input="changed('phone')"/></div><p v-if="fieldError.phone" class="qph-error">{{ct(fieldError.phone)}}</p>
   <template v-if="mode==='register'"><label :for="nameId">{{ct('登录名')}}</label><input :id="nameId" v-model="form.username" class="qph-input" autocomplete="username" maxlength="20" :disabled="locked" :placeholder="ct('为你的账户取一个登录名')" @focus="focus('username')" @blur="focus('none')" @input="changed('username')"/></template>
   <PhoneCodeCard v-if="mode!=='login'" v-model="form.code" :phone="form.phone" :purpose="purpose" :policy="policy" :active="active" :disabled="locked" @busy="codeBusy=$event"/>
   <label :for="passwordId">{{ct(mode==='login'?'登录密码':mode==='register'?'设置登录密码':'新的登录密码')}}</label><div class="qph-password"><input :id="passwordId" v-model="form.password" class="qph-input" :type="visible?'text':'password'" :autocomplete="mode==='login'?'current-password':'new-password'" :maxlength="mode==='login'?128:32" :disabled="locked" :placeholder="ct(mode==='login'?'填写这个账户的密码':'8–32 个字符')" @focus="focus('password')" @blur="focus('none')" @input="changed('password')"/><button type="button" :aria-label="ct(visible?'隐藏密码':'显示密码')" :aria-pressed="visible" :disabled="locked" @mousedown.prevent @click="visible=!visible;interaction()">{{visible?'◒':'◉'}}</button></div>
   <template v-if="mode!=='login'"><label :for="confirmId">{{ct('再次填写密码')}}</label><input :id="confirmId" v-model="form.confirmation" class="qph-input" :type="visible?'text':'password'" autocomplete="new-password" maxlength="32" :disabled="locked" :placeholder="ct('再确认一次这把钥匙')" @focus="focus('password')" @blur="focus('none')" @input="changed('confirmation')"/><p class="qph-small">{{ct(mode==='forget'?'8–32 字符；管理员至少 12 字符，含英文字母和数字':'8–32 个字符')}}</p></template>
   <template v-if="mode==='register'"><label :for="inviteId">{{ct('邀请码（选填）')}}</label><input :id="inviteId" v-model="form.inviteCode" class="qph-input" autocomplete="off" maxlength="64" :disabled="locked" :placeholder="ct('有朋友邀请你来吗？')" @input="changed('inviteCode')"/></template>
   <div v-if="mode==='login'" class="qph-assist"><label><input :checked="remember" type="checkbox" :disabled="locked" @change="$emit('remember-change',$event.target.checked)"/>{{ct('记住登录30天')}}</label><button type="button" :disabled="locked" @click="$emit('mode-change','forget')">{{ct('忘记密码？')}}</button></div>
   <div v-if="pendingAction" class="qph-pending" role="status"><b>{{ct('先核对，刚才的那一步。')}}</b><p>{{ct('结果确认前保留当前内容，不会自动重新提交。')}}</p><div><button type="button" :disabled="busy" @click="readAction">{{ct('核对刚才的处理')}}</button><button type="button" :disabled="busy" @click="reviewClose">{{ct('结束这次等待')}}</button></div></div>
   <p v-if="error" class="qph-error" role="alert">{{ct(error)}}</p><p v-if="notice" class="qph-small" role="status">{{ct(notice)}}</p>
   <button class="qph-primary qph-submit" type="submit" :disabled="locked||codeBusy||!policy||mode==='login'&&!policy.passwordEnabled||mode==='register'&&(!registerEnabled||!policy.registrationEnabled)" :aria-busy="busy"><BrandLoader v-if="busy" :size="18"/>{{ct(busy?'正在处理…':mode==='login'?'登录我的空间':mode==='register'?'创建并进入空间':'确认新的登录密码')}}<span v-if="!busy" aria-hidden="true">↗</span></button>
   <p v-if="policy&&mode==='register'&&!policy.registrationEnabled" class="qph-small">{{ct('注册暂未开放，已有账户仍可登录。')}}</p>
  </form>
  <dialog ref="closeDialog" class="qph-dialog" :aria-labelledby="'qph-action-close-title-'+id" @cancel.prevent="closeDialog?.close()"><span class="qph-eyebrow">KNOW WHERE YOU LEFT OFF</span><h3 :id="'qph-action-close-title-'+id">{{ct('结束这次账户等待？')}}</h3><p>{{ct('尚未完成的请求将结束。已经完成的注册或密码修改会保留，不会自动撤销。')}}</p><p v-if="error" class="qph-error" role="alert">{{ct(error)}}</p><footer><button type="button" @click="closeDialog?.close()">{{ct('再等等')}}</button><button type="button" class="qph-primary" :disabled="busy" @click="finishClose">{{ct('确认结束等待')}}</button></footer></dialog>
 </section>
</template>
<script setup>
import {computed,nextTick,onBeforeUnmount,reactive,ref,useId,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {api} from '../../api/client.js';import {useAuth} from '../../stores/auth.js';import {currentLang} from '../../i18n/index.js';import {accountText} from '../../i18n/account-messages.js';import {passwordProblem} from '../../lib/account-profile.js';import {newPhoneKey,normalizedPhone,phoneActionReceipt,phonePolicy,phoneProblem} from '../../lib/phone-identity.js';import {readPhonePending,savePhonePending} from '../../lib/phone-pending.js';import BrandLoader from '../design/BrandLoader.vue';import PhoneCodeCard from './PhoneCodeCard.vue';import './phone-identity.css';
const props=defineProps({mode:{type:String,default:'login'},active:Boolean,agreed:Boolean,remember:{type:Boolean,default:true},registerEnabled:Boolean}),emit=defineEmits(['mode-change','remember-change','consent-required','interaction','busy']),auth=useAuth(),route=useRoute(),router=useRouter(),ct=(key,params)=>accountText(currentLang.value,key,params),id=useId(),phoneId='qph-phone-'+id,nameId='qph-name-'+id,passwordId='qph-password-'+id,confirmId='qph-confirm-'+id,inviteId='qph-invite-'+id,form=reactive({phone:'',username:'',password:'',confirmation:'',code:'',inviteCode:''}),fieldError=reactive({}),visible=ref(false),focused=ref('none'),policy=ref(null),policyLoading=ref(false),busy=ref(false),codeBusy=ref(false),error=ref(''),notice=ref(''),pendingAction=ref(null),closeDialog=ref(null),reviewVersion=ref(0),purpose=computed(()=>props.mode==='register'?'register':'recover'),locked=computed(()=>busy.value||!!pendingAction.value);
let alive=true,controller,epoch=0,policyController,policyEpoch=0;const owner=()=>auth.user?.id||'guest',stamp=()=>({owner:owner(),revision:auth.identityRevision,mode:props.mode}),current=at=>alive&&props.active&&at.owner===owner()&&at.revision===auth.identityRevision&&at.mode===props.mode;
function setBusy(value){busy.value=value;emit('busy',value);}function interaction(){emit('interaction',{isTyping:focused.value!=='none',passwordLength:form.password.length,isPasswordFocus:focused.value==='password',isPasswordVisible:visible.value,focusedField:focused.value==='phone'?'email':focused.value,isLoginError:!!error.value});}function focus(value){focused.value=value;interaction();}function changed(key){delete fieldError[key];error.value='';notice.value='';interaction();}function rememberAction(row){pendingAction.value=row;return savePhonePending('action',owner(),purpose.value,row);}function cancel(){epoch++;controller?.abort();controller=null;setBusy(false);closeDialog.value?.close();}
async function loadPolicy(){policyController?.abort();const request=new AbortController(),version=++policyEpoch,at=stamp();policyController=request;policyLoading.value=true;try{const row=await api.get('/auth/phone/policy',{signal:request.signal,retry:false});if(!current(at)||request.signal.aborted||version!==policyEpoch)return;if(!phonePolicy(row))throw Error('暂时无法确认手机服务，请重新读取。');policy.value=row;}catch(e){if(current(at)&&!request.signal.aborted&&version===policyEpoch){policy.value=null;error.value=e.message||'暂时无法确认手机服务，请重新读取。';}}finally{if(current(at)&&version===policyEpoch)policyLoading.value=false;}}
function validation(){const problem=phoneProblem(form.phone);if(problem){fieldError.phone=problem;return problem;}if(!form.password)return'请填写登录密码。';if(props.mode==='login')return'';if(!/^\d{6}$/.test(form.code))return'请填写六位短信验证码。';const password=passwordProblem('',form.password,form.confirmation,false,false);if(password)return password;if(props.mode==='register'&&!/^[a-zA-Z0-9_-]{3,20}$/.test(form.username.trim()))return'登录名需为 3–20 位字母、数字、下划线或短横线。';return'';}
function destination(){const value=route.query.redirect;return typeof value==='string'&&value.startsWith('/')&&!value.startsWith('//')?value:'/chat';}
async function login(at,version,phone=form.phone,password=form.password){const row=await api.post('/auth/phone/login',{phone:normalizedPhone(phone),password},{signal:controller.signal,retry:false});if(!current(at)||version!==epoch)return;auth.acceptLogin(row,{remember:props.remember});await router.push(destination());}
async function completed(row,{automatic=false,at,version,submitted}={}){
  rememberAction(null);form.code='';
  if(row.status==='closed'){notice.value='这次账户等待已结束，已完成的操作会保留。';return;}
  if(props.mode==='register'&&automatic){
    notice.value='账户已创建，正在进入你的空间。';
    try{await login(at,version,submitted.phone,submitted.password);}
    catch(e){if(current(at)&&version===epoch){notice.value='账户已创建，登录尚未完成。请使用手机号与密码登录。';error.value=e.message;emit('mode-change','login');}}
    return;
  }
  let expected=stamp();
  if(props.mode==='forget'&&auth.isLoggedIn){
    try{const person=await api.get('/auth/me',{signal:controller?.signal,retry:false});if(!current(expected))return;if(person?.id!==expected.owner)throw Error('当前登录状态尚未确认。');}
    catch(e){if(!current(expected))return;if(e.status===401){auth.clearLocal('password-changed');expected=stamp();await nextTick();}else error.value='密码找回已完成，当前登录状态暂未核对。';}
  }
  if(!current(expected))return;
  form.password='';form.confirmation='';notice.value=props.mode==='register'?'刚才的注册已完成，请使用手机号与密码登录。':'刚才的密码找回已完成，请使用新密码登录。';emit('mode-change','login');
}
async function submit(){if(locked.value||codeBusy.value||!props.active||!policy.value)return;error.value=validation();if(error.value){interaction();return;}if(props.mode!=='forget'&&!props.agreed){emit('consent-required');return;}if(props.mode==='register'&&(!props.registerEnabled||!policy.value.registrationEnabled)){error.value='注册暂未开放，已有账户仍可登录。';return;}if(props.mode==='login'&&!policy.value.passwordEnabled){error.value='手机密码登录暂未开放，请使用其他登录方式。';return;}const at=stamp(),version=++epoch;controller=new AbortController();setBusy(true);notice.value='';try{if(props.mode==='login'){await login(at,version);return;}const key=newPhoneKey(),body={purpose:purpose.value,phone:normalizedPhone(form.phone),code:form.code,password:form.password,confirmation:form.confirmation,...(props.mode==='register'?{username:form.username.trim(),inviteCode:form.inviteCode.trim()}:{}),expectedVersion:0};if(!rememberAction({key,operationVersion:0})){rememberAction(null);throw Object.assign(Error('浏览器未能保存处理编号，本次申请尚未提交。'),{status:422});}const row=await api.post('/auth/phone/actions/'+key,body,{signal:controller.signal,retry:false});if(!current(at)||version!==epoch)return;if(!phoneActionReceipt(row,key,purpose.value))throw Error('账户处理结果不完整，请核对原结果。');await completed(row,{automatic:true,at,version,submitted:body});}catch(e){if(current(at)&&version===epoch){if([400,422,429,503].includes(e.status))rememberAction(null);error.value=e.message||(props.mode==='login'?'登录结果尚未确认，可以稍后再试。':'账户处理结果尚未确认，请核对原结果。');interaction();}}finally{if(current(at)&&version===epoch)setBusy(false);}}
async function readAction(){if(!pendingAction.value||busy.value)return;const at=stamp(),version=++epoch,key=pendingAction.value.key;controller=new AbortController();setBusy(true);error.value='';try{const row=await api.get('/auth/phone/actions/'+key,{signal:controller.signal,retry:false});if(!current(at)||version!==epoch)return;if(!phoneActionReceipt(row,key,purpose.value))throw Error('账户处理结果不完整，请核对原结果。');await completed(row);}catch(e){if(current(at)&&version===epoch)error.value=e.status===404?'暂未找到这次处理，可稍后核对或明确结束等待。':e.message;}finally{if(current(at)&&version===epoch)setBusy(false);}}
async function reviewClose(){if(!pendingAction.value||busy.value)return;const at=stamp(),version=++epoch,key=pendingAction.value.key;controller=new AbortController();setBusy(true);error.value='';try{let row,missing=false;try{row=await api.get('/auth/phone/actions/'+key,{signal:controller.signal,retry:false});}catch(e){if(e.status!==404)throw e;missing=true;row={version:0};}if(!current(at)||version!==epoch)return;if(!missing&&!phoneActionReceipt(row,key,purpose.value))throw Error('账户处理结果不完整，请核对原结果。');reviewVersion.value=row.version;await nextTick();closeDialog.value?.showModal();}catch(e){if(current(at)&&version===epoch)error.value=e.message;}finally{if(current(at)&&version===epoch)setBusy(false);}}
async function finishClose(){if(!pendingAction.value||busy.value)return;const at=stamp(),version=++epoch,key=pendingAction.value.key;controller=new AbortController();setBusy(true);error.value='';try{const row=await api.post('/auth/phone/actions/'+key+'/close',{purpose:purpose.value,expectedVersion:reviewVersion.value},{signal:controller.signal,retry:false});if(!current(at)||version!==epoch)return;if(!phoneActionReceipt(row,key,purpose.value))throw Error('账户处理结果不完整，请核对原结果。');await completed(row);closeDialog.value?.close();}catch(e){if(current(at)&&version===epoch)error.value=e.status===409?'这次处理已有变化，请重新核对。':e.message;}finally{if(current(at)&&version===epoch)setBusy(false);}}
watch([()=>props.active,()=>props.mode,()=>auth.user?.id,()=>auth.identityRevision],([active,mode,userId,revision],[previousActive,previousMode,previousId,previousRevision]=[])=>{cancel();policyController?.abort();policyEpoch++;policyLoading.value=false;visible.value=false;focused.value='none';error.value='';for(const key of Object.keys(fieldError))delete fieldError[key];if(mode!==previousMode||userId!==previousId||revision!==previousRevision){form.code='';form.password='';form.confirmation='';}if(userId!==previousId||revision!==previousRevision){form.phone='';form.username='';form.inviteCode='';notice.value='';}pendingAction.value=active&&mode!=='login'?readPhonePending('action',owner(),purpose.value):null;if(active)void loadPolicy();interaction();},{immediate:true});
onBeforeUnmount(()=>{alive=false;cancel();policyController?.abort();form.password='';form.confirmation='';form.code='';});defineExpose({submit});
</script>
